# -*- coding: utf-8 -*-

"""
requests.auth
~~~~~~~~~~~~~

This module contains the authentication handlers for Requests.

Security hardenings applied:
- Use secrets.token_hex for cnonce
- Use a whitelisted algorithm map and hashlib.new for hashing
- Parse qop tokens explicitly
- Use hmac.compare_digest for equality checks
- More defensive per-thread initialization and counters
"""

import os
import re
import time
import hashlib
import threading
import warnings
import secrets
import hmac

from base64 import b64encode

from .compat import urlparse, str, basestring
from .cookies import extract_cookies_to_jar
from ._internal_utils import to_native_string
from .utils import parse_dict_header

CONTENT_TYPE_FORM_URLENCODED = 'application/x-www-form-urlencoded'
CONTENT_TYPE_MULTI_PART = 'multipart/form-data'


def _basic_auth_str(username, password):
    """Returns a Basic Auth string."""

    # Backwards compatibility warnings for non-string inputs.
    if not isinstance(username, basestring):
        warnings.warn(
            "Non-string usernames will no longer be supported in Requests "
            "3.0.0. Please convert the object you've passed in ({!r}) to "
            "a string or bytes object in the near future to avoid "
            "problems.".format(username),
            category=DeprecationWarning,
        )
        username = str(username)

    if not isinstance(password, basestring):
        warnings.warn(
            "Non-string passwords will no longer be supported in Requests "
            "3.0.0. Please convert the object you've passed in ({!r}) to "
            "a string or bytes object in the near future to avoid "
            "problems.".format(password),
            category=DeprecationWarning,
        )
        password = str(password)

    if isinstance(username, str):
        username = username.encode('latin1')

    if isinstance(password, str):
        password = password.encode('latin1')

    authstr = 'Basic ' + to_native_string(
        b64encode(b':'.join((username, password))).strip()
    )

    return authstr


class AuthBase(object):
    """Base class that all auth implementations derive from"""

    def __call__(self, r):
        raise NotImplementedError('Auth hooks must be callable.')


class HTTPBasicAuth(AuthBase):
    """Attaches HTTP Basic Authentication to the given Request object."""

    def __init__(self, username, password):
        self.username = username
        self.password = password

    def __eq__(self, other):
        # Constant-time compare for username and password where possible.
        other_username = getattr(other, 'username', None)
        other_password = getattr(other, 'password', None)
        if other_username is None or other_password is None:
            return False
        try:
            return (hmac.compare_digest(
                        (self.username or "").encode('utf-8'),
                        (other_username or "").encode('utf-8')
                    ) and
                    hmac.compare_digest(
                        (self.password or "").encode('utf-8'),
                        (other_password or "").encode('utf-8')
                    ))
        except Exception:
            # Fallback - safe non-raising compare
            return (self.username == other_username and self.password == other_password)

    def __ne__(self, other):
        return not self == other

    def __call__(self, r):
        # Warning: Basic auth sends credentials on every request. Ensure TLS.
        if r.url and not r.url.lower().startswith('https://'):
            warnings.warn("Using HTTP Basic Authentication over non-HTTPS URL is insecure.", category=RuntimeWarning)
        r.headers['Authorization'] = _basic_auth_str(self.username, self.password)
        return r


class HTTPProxyAuth(HTTPBasicAuth):
    """Attaches HTTP Proxy Authentication to a given Request object."""

    def __call__(self, r):
        if r.url and not r.url.lower().startswith('https://'):
            # Proxy auth may be required for CONNECT tunnelling; still warn.
            warnings.warn("Using HTTP Proxy Authentication over non-HTTPS URL is insecure.", category=RuntimeWarning)
        r.headers['Proxy-Authorization'] = _basic_auth_str(self.username, self.password)
        return r


class HTTPDigestAuth(AuthBase):
    """Attaches HTTP Digest Authentication to the given Request object."""

    def __init__(self, username, password):
        self.username = username
        self.password = password
        # Keep state in per-thread local storage
        self._thread_local = threading.local()

    def init_per_thread_state(self):
        # Ensure state is initialized just once per-thread, defensively.
        if not getattr(self._thread_local, 'init', False):
            self._thread_local.init = True
            self._thread_local.last_nonce = ''
            self._thread_local.nonce_count = 0
            self._thread_local.chal = {}
            self._thread_local.pos = None
            # num_401_calls tracks how many 401-handling attempts we've made for a given request
            self._thread_local.num_401_calls = 0

    def build_digest_header(self, method, url):
        """
        Build and return a Digest Authorization header string, or None on failure.
        This implementation enforces a whitelist of algorithms and uses strong randomness for cnonce.
        """

        # Retrieve challenge fields
        chal = self._thread_local.chal or {}
        realm = chal.get('realm')
        nonce = chal.get('nonce')
        qop = chal.get('qop')
        algorithm = chal.get('algorithm')
        opaque = chal.get('opaque')

        if realm is None or nonce is None:
            # Missing required challenge fields
            return None

        # Algorithm whitelist: map token -> hashlib name
        _algo_map = {
            'MD5': 'md5',
            'MD5-SESS': 'md5',
            'SHA': 'sha1',
            'SHA-256': 'sha256',
            'SHA-512': 'sha512',
        }

        _algorithm = (algorithm or 'MD5').upper()

        if _algorithm not in _algo_map:
            warnings.warn(
                "Digest auth requested unknown/unsupported algorithm %r; refusing to build header." % (algorithm,),
                category=RuntimeWarning
            )
            return None

        hash_name = _algo_map[_algorithm]

        def hash_utf8(x):
            if isinstance(x, str):
                x = x.encode('utf-8')
            h = hashlib.new(hash_name)
            h.update(x)
            return h.hexdigest()

        # KD as in RFC: KD(secret, data) = H(concat(secret, ":", data))
        KD = lambda s, d: hash_utf8("%s:%s" % (s, d))

        # entity body digest (auth-int) not implemented here
        entdig = None

        # Build request path (request-uri)
        p_parsed = urlparse(url)
        path = p_parsed.path or "/"
        if p_parsed.query:
            path += '?' + p_parsed.query

        # A1/A2
        A1 = '%s:%s:%s' % (self.username, realm, self.password)
        A2 = '%s:%s' % (method, path)

        HA1 = hash_utf8(A1)
        HA2 = hash_utf8(A2)

        # Manage nonce_count
        if nonce == getattr(self._thread_local, 'last_nonce', None):
            self._thread_local.nonce_count = getattr(self._thread_local, 'nonce_count', 0) + 1
        else:
            self._thread_local.nonce_count = 1

        ncvalue = '%08x' % self._thread_local.nonce_count

        # Strong cnonce generation
        cnonce = secrets.token_hex(8)  # 16 hex chars, cryptographically secure

        if _algorithm == 'MD5-SESS':
            HA1 = hash_utf8('%s:%s:%s' % (HA1, nonce, cnonce))

        # qop handling: explicit parsing and check for 'auth'
        if not qop:
            respdig = KD(HA1, "%s:%s" % (nonce, HA2))
        else:
            qop_tokens = [t.strip() for t in qop.split(',') if t.strip()]
            if 'auth' in qop_tokens:
                noncebit = "%s:%s:%s:%s:%s" % (nonce, ncvalue, cnonce, 'auth', HA2)
                respdig = KD(HA1, noncebit)
            else:
                # auth-int would require entity-body digest handling — not implemented
                warnings.warn("qop does not include 'auth' and auth-int is not implemented.", category=RuntimeWarning)
                return None

        # persist last_nonce for same-thread reuse to avoid an unnecessary 401 round-trip
        self._thread_local.last_nonce = nonce

        # Build header string (quote values as RFC suggests)
        base = 'username="%s", realm="%s", nonce="%s", uri="%s", response="%s"' % (
            self.username, realm, nonce, path, respdig
        )
        if opaque:
            base += ', opaque="%s"' % opaque
        if algorithm:
            base += ', algorithm="%s"' % algorithm
        if entdig:
            base += ', digest="%s"' % entdig
        if qop:
            base += ', qop="auth", nc=%s, cnonce="%s"' % (ncvalue, cnonce)

        return 'Digest %s' % (base)

    def handle_redirect(self, r, **kwargs):
        """Reset num_401_calls counter on redirects so future 401s can be retried once."""
        if getattr(r, 'is_redirect', False):
            self._thread_local.num_401_calls = 0

    def handle_401(self, r, **kwargs):
        """
        Takes the given response and tries digest-auth, if needed.

        :rtype: requests.Response
        """

        # Only attempt when response is a 4xx (usually 401)
        if not 400 <= getattr(r, 'status_code', 0) < 500:
            self._thread_local.num_401_calls = 0
            return r

        # If we have a saved position for a file-like body, rewind it so we can resend
        if getattr(self._thread_local, 'pos', None) is not None:
            try:
                r.request.body.seek(self._thread_local.pos)
            except Exception:
                # If the body can't be seeked, we'll let it fail or server may reject.
                self._thread_local.pos = None

        s_auth = r.headers.get('www-authenticate', '')

        # If digest challenge present and we haven't retried too many times
        if 'digest' in s_auth.lower() and getattr(self._thread_local, 'num_401_calls', 0) < 2:
            self._thread_local.num_401_calls += 1

            # Parse challenge into dictionary for use by build_digest_header
            pat = re.compile(r'digest ', flags=re.IGNORECASE)
            self._thread_local.chal = parse_dict_header(pat.sub('', s_auth, count=1))

            # Consume response content and close to free connection for reuse
            r.content
            r.close()

            # Prepare a new request (copy) and attach cookies from original
            prep = r.request.copy()
            extract_cookies_to_jar(prep._cookies, r.request, r.raw)
            prep.prepare_cookies(prep._cookies)

            # build Authorization header
            auth_header = self.build_digest_header(prep.method, prep.url)
            if auth_header is None:
                # Could not build header (unsupported algorithm or qop), abort retry
                self._thread_local.num_401_calls = 0
                return r

            prep.headers['Authorization'] = auth_header

            # Send the prepared request using the same connection
            _r = r.connection.send(prep, **kwargs)
            _r.history.append(r)
            _r.request = prep

            return _r

        # Either not a digest challenge or we've already retried; reset counter and return original
        self._thread_local.num_401_calls = 0
        return r

    def __call__(self, r):
        # Initialize per-thread state if needed
        self.init_per_thread_state()

        # If we have a saved nonce from previous exchange, pre-emptively set Authorization to avoid 401
        if getattr(self._thread_local, 'last_nonce', None):
            hdr = self.build_digest_header(r.method, r.url)
            if hdr is not None:
                # Warn about non-HTTPS usage
                if r.url and not r.url.lower().startswith('https://'):
                    warnings.warn("Using Digest Authentication over non-HTTPS URL is insecure.", category=RuntimeWarning)
                r.headers['Authorization'] = hdr

        # Try to remember body position if body is seekable so we can resend on 401
        try:
            self._thread_local.pos = r.body.tell()
        except Exception:
            self._thread_local.pos = None

        # Register hooks to handle 401 responses and redirects
        r.register_hook('response', self.handle_401)
        r.register_hook('response', self.handle_redirect)

        # Reset per-request 401 attempt counter
        self._thread_local.num_401_calls = 0

        return r

    def __eq__(self, other):
        # Constant-time compare for username/password where possible
        other_username = getattr(other, 'username', None)
        other_password = getattr(other, 'password', None)
        if other_username is None or other_password is None:
            return False
        try:
            return (hmac.compare_digest(
                        (self.username or "").encode('utf-8'),
                        (other_username or "").encode('utf-8')
                    ) and
                    hmac.compare_digest(
                        (self.password or "").encode('utf-8'),
                        (other_password or "").encode('utf-8')
                    ))
        except Exception:
            return (self.username == other_username and self.password == other_password)

    def __ne__(self, other):
        return not self == other
